let blRigCount=0;function blRig(variant=''){const id=++blRigCount;const pageProps={code:'<g class="cap-prop"><rect x="70" y="40" width="21" height="16" rx="3" fill="#fff" stroke="#17385f" stroke-width="1.5"/><path d="m77 45-3 3 3 3m6-6 3 3-3 3" fill="none" stroke="#62b3e7" stroke-width="1.7"/></g>',compass:'<g class="cap-prop"><circle cx="81" cy="48" r="9" fill="#fff" stroke="#17385f" stroke-width="1.8"/><path d="m84 44-2 6-5 2 2-6z" fill="#ecaa59" stroke="#17385f" stroke-width="1"/></g>',wallet:'<g class="cap-prop"><rect x="71" y="42" width="19" height="15" rx="3" fill="#eab16d" stroke="#17385f" stroke-width="1.6"/><path d="M82 47h8v5h-8a2.5 2.5 0 0 1 0-5z" fill="#fff" stroke="#17385f" stroke-width="1.2"/></g>',shield:'<g class="cap-prop"><path d="M80 39 89 42v8c0 6-5 9-9 11-5-2-9-5-9-11v-8z" fill="#bce8ff" stroke="#17385f" stroke-width="1.6"/><path d="m76 50 3 3 5-6" fill="none" stroke="#17385f" stroke-width="1.5"/></g>',coin:'<g class="cap-prop"><circle cx="81" cy="48" r="9" fill="#f1bd71" stroke="#17385f" stroke-width="1.8"/><path d="M81 43v10m3-8h-4a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4h-4" fill="none" stroke="#17385f" stroke-width="1.4"/></g>',letter:'<g class="cap-prop"><rect x="70" y="41" width="20" height="15" rx="2" fill="#fff" stroke="#17385f" stroke-width="1.5"/><path d="m71 43 9 7 9-7" fill="none" stroke="#72b6df" stroke-width="1.5"/></g>',book:'<g class="cap-prop"><path d="M70 42q6-2 10 1 4-3 10-1v15q-6-2-10 1-4-3-10-1z" fill="#fff" stroke="#17385f" stroke-width="1.5"/><path d="M80 43v15m-7-12h4m6 0h4" fill="none" stroke="#72b6df" stroke-width="1.2"/></g>'};const prop=pageProps[variant]||(variant==='markets'?'<g class="cap-prop"><circle cx="82" cy="45" r="6.5" fill="#d7f2ff" stroke="#17385f" stroke-width="2"/><path d="M77 50 73 55" stroke="#17385f" stroke-width="2.5" stroke-linecap="round"/></g>':variant==='quotes'?'<g class="cap-prop"><rect x="70" y="39" width="20" height="13" rx="4" fill="white" stroke="#17385f" stroke-width="1.4"/><path d="M74 45h12M74 48h8" stroke="#65a9d6" stroke-width="1.5" stroke-linecap="round"/></g>':variant==='risk'?'<g class="cap-prop"><rect x="72" y="41" width="16" height="20" rx="2" fill="white" stroke="#17385f" stroke-width="1.4"/><path d="M75 47h10M75 51h10M75 55h7" stroke="#65a9d6" stroke-width="1.3" stroke-linecap="round"/></g>':'');return `<svg class="cap-rig cap-rig--${variant || 'hero'}" viewBox="0 0 100 100" aria-hidden="true"><defs><linearGradient id="cap-limb-${id}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#f4fbff"/><stop offset="1" stop-color="#a4d5f5"/></linearGradient><radialGradient id="cap-shadow-${id}"><stop stop-color="#5a8aa8" stop-opacity=".28"/><stop offset="1" stop-color="#5a8aa8" stop-opacity="0"/></radialGradient></defs><ellipse cx="50" cy="85" rx="33" ry="4" fill="url(#cap-shadow-${id})"/><g class="cap-jump"><g class="cap-foot cap-foot-left"><ellipse cx="38" cy="79" rx="7.5" ry="5.8" fill="url(#cap-limb-${id})" stroke="#17385f" stroke-width="2.3"/></g><g class="cap-foot cap-foot-right"><ellipse cx="62" cy="79" rx="7.5" ry="5.8" fill="url(#cap-limb-${id})" stroke="#17385f" stroke-width="2.3"/></g><g class="cap-breathe"><g class="cap-arm cap-arm-left"><ellipse cx="24" cy="54" rx="5.4" ry="8.5" fill="url(#cap-limb-${id})" stroke="#17385f" stroke-width="2.3"/></g><g class="cap-arm cap-arm-right"><ellipse cx="76" cy="54" rx="5.4" ry="8.5" fill="url(#cap-limb-${id})" stroke="#17385f" stroke-width="2.3"/></g><image href="assets/capstan-body.webp" x="0" y="0" width="100" height="100"/><g class="cap-face"><ellipse cx="32.5" cy="52.5" rx="4.2" ry="2.4" fill="#f8a6bc"/><ellipse cx="67.5" cy="52.5" rx="4.2" ry="2.4" fill="#f8a6bc"/><g class="cap-happy-eyes"><path d="M36.6 48 Q40 43.5 43.4 48 M56.6 48 Q60 43.5 63.4 48" fill="none" stroke="#17385f" stroke-width="1.8" stroke-linecap="round"/></g><g class="cap-eye cap-eye-left"><ellipse cx="40" cy="48" rx="3.1" ry="4.1" fill="#17385f"/><circle cx="39" cy="46.5" r="1.15" fill="#fff"/><circle cx="41.1" cy="49" r=".55" fill="#fff"/></g><path class="cap-wink" d="M57 48 Q60 45 63 48" fill="none" stroke="#17385f" stroke-width="1.7" stroke-linecap="round"/><g class="cap-eye cap-eye-right"><ellipse cx="60" cy="48" rx="3.1" ry="4.1" fill="#17385f"/><circle cx="59" cy="46.5" r="1.15" fill="#fff"/><circle cx="61.1" cy="49" r=".55" fill="#fff"/></g><g class="cap-mouth-open"><path d="M46.6 53.2 Q50 55.2 53.4 53.2 Q52.7 57.3 50 57.5 Q47.2 57.3 46.6 53.2Z" fill="#17385f"/><ellipse cx="50" cy="56.2" rx="1.6" ry=".8" fill="#ff98b0"/></g><path class="cap-mouth-smile" d="M46 54 Q50 58 54 54" fill="none" stroke="#17385f" stroke-width="1.6" stroke-linecap="round"/><path class="cap-brows" d="M36 42 Q39 40 42 42 M58 42 Q61 40 64 42" fill="none" stroke="#17385f" stroke-width="1.5" stroke-linecap="round"/></g>${prop}</g></g></svg>`}
