const blMascot=(kind='wave',extra='')=>`<img class="bl-mascot ${extra}" src="${({wave:'assets/capstan-wave.webp',read:'assets/capstan-read.webp',search:'assets/capstan-search.webp',body:'assets/capstan-body.webp'})[kind]||'assets/capstan-wave.webp'}" width="720" height="720" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='assets/mascot-3d.png'" alt="Capstan mascot">`;
