function setupBloopTimeline(){const root=document.querySelector('.bl-stepper');if(!root)return;const buttons=[...root.querySelectorAll('[data-step]')],reduce=matchMedia('(prefers-reduced-motion: reduce)');let visible=false,hovered=false,focused=false,timer=0;function schedule(){clearTimeout(timer);if(!visible||hovered||focused||document.hidden||reduce.matches)return;timer=setTimeout(()=>{const i=buttons.findIndex(b=>b.classList.contains('active'));buttons[(i+1)%buttons.length].click()},6500)}root.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'){hovered=true;schedule()}});root.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse'){hovered=false;schedule()}});root.addEventListener('focusin',()=>{focused=true;schedule()});root.addEventListener('focusout',e=>{focused=root.contains(e.relatedTarget);schedule()});root.addEventListener('click',schedule);root.addEventListener('keydown',e=>{if(e.key!=='ArrowRight'&&e.key!=='ArrowLeft')return;e.preventDefault();const i=buttons.findIndex(b=>b.classList.contains('active')),next=(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].click();buttons[next].focus()});document.addEventListener('visibilitychange',schedule);reduce.addEventListener?.('change',schedule);if('IntersectionObserver'in window)new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;schedule()},{threshold:.1}).observe(root);else{visible=true;schedule()}}
